import{_ as t,o as r,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const d=JSON.parse('{"title":"产品发布 - 2026-06-15","description":"","frontmatter":{"date":"2026-06-15T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-06-15-product.md","filePath":"daily/2026-06-15-product.md"}'),e={name:"daily/2026-06-15-product.md"};function i(s,o,p,l,g,h){return r(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="产品发布-2026-06-15" tabindex="-1">产品发布 - 2026-06-15 <a class="header-anchor" href="#产品发布-2026-06-15" aria-label="Permalink to &quot;产品发布 - 2026-06-15&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日产品发布领域主要动态包括：Notion计划推出非AI新功能，微软发布基于大型语言模型的人工智能聊天机器人Copilot，数字.ai推出23.3版本工作流概览，产品副驾驶作为AI助手集成于Jira和Confluence中，以及微软面向组织推出的AI工具Copilot。最值得关注的是微软的Copilot，它不仅作为一款AI聊天机器人，还特别针对组织推出了基于聊天的生成式AI工具，旨在提升工作效率和安全性。</p><hr><h3 id="_1-今年notion将推出哪些非ai功能" tabindex="-1">1. 今年Notion将推出哪些非AI功能？ <a class="header-anchor" href="#_1-今年notion将推出哪些非ai功能" aria-label="Permalink to &quot;1. 今年Notion将推出哪些非AI功能？&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.reddit.com/r/Notion/comments/1qbod39/what_new_features_will_come_to_notion_this_year" target="_blank" rel="noreferrer">What new features will come to Notion this year that are not AI-based?</a></p><p><strong>一句话摘要</strong>: 讨论Notion今年可能推出的非AI新功能。</p><p><strong>能解决什么问题</strong>: 提供Notion用户期待的非AI功能改进和新特性。</p><p><strong>产品应用</strong>: 可以应用到Notion产品中，提升用户体验和工作效率。</p><p><strong>示例场景</strong>: 团队成员通过Notion数据库实时讨论项目。</p><hr><h3 id="_2-微软copilot-维基百科" tabindex="-1">2. 微软Copilot - 维基百科 <a class="header-anchor" href="#_2-微软copilot-维基百科" aria-label="Permalink to &quot;2. 微软Copilot - 维基百科&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Microsoft_Copilot" target="_blank" rel="noreferrer">Microsoft Copilot - Wikipedia</a></p><p><strong>一句话摘要</strong>: 微软基于大型语言模型开发的人工智能聊天机器人</p><p><strong>能解决什么问题</strong>: 替代已停用的Cortana，提供智能助手服务</p><p><strong>产品应用</strong>: 可集成到Windows和Microsoft 365，适用于企业自动化和个性化服务</p><p><strong>示例场景</strong>: 企业通过Copilot Studio创建定制化AI助手</p><hr><h3 id="_3-数字-ai发布23-3版本工作流概览" tabindex="-1">3. 数字.ai发布23.3版本工作流概览 <a class="header-anchor" href="#_3-数字-ai发布23-3版本工作流概览" aria-label="Permalink to &quot;3. 数字.ai发布23.3版本工作流概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: 数字.ai发布23.3版本引入自助工作流简化应用上线。</p><p><strong>能解决什么问题</strong>: 帮助开发者在缺乏工具知识的情况下轻松上线应用。</p><p><strong>产品应用</strong>: 适用于需要简化云应用部署和管理的产品。</p><p><strong>示例场景</strong>: 开发者使用工作流自动化部署云应用。</p><hr><h3 id="_4-产品副驾驶——软件产品团队的ai助手" tabindex="-1">4. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_4-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;4. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: 产品副驾驶是集成在Jira和Confluence中的AI助手，帮助产品团队提高效率。</p><p><strong>能解决什么问题</strong>: 解决产品团队在管理用户故事、协作和产品开发中的效率问题。</p><p><strong>产品应用</strong>: 适用于需要优化产品管理流程和提高工作效率的产品团队。</p><p><strong>示例场景</strong>: 产品负责人使用产品副驾驶创建清晰的用户故事和维护文档。</p><hr><h3 id="_5-微软copilot-面向组织的ai工具" tabindex="-1">5. 微软Copilot | 面向组织的AI工具 <a class="header-anchor" href="#_5-微软copilot-面向组织的ai工具" aria-label="Permalink to &quot;5. 微软Copilot | 面向组织的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软推出基于聊天的生成式AI工具，提升工作效率和安全性。</p><p><strong>能解决什么问题</strong>: 提高组织工作效率，加强安全防护，同时保持合规性。</p><p><strong>产品应用</strong>: 可应用于企业日常运营，如写作、编程、安全防护等场景。</p><p><strong>示例场景</strong>: 企业员工使用Copilot辅助撰写工作报告和分析数据。</p><hr><h3 id="_6-figma-ai工具对所有用户的发布日期" tabindex="-1">6. Figma AI工具对所有用户的发布日期 <a class="header-anchor" href="#_6-figma-ai工具对所有用户的发布日期" aria-label="Permalink to &quot;6. Figma AI工具对所有用户的发布日期&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://forum.figma.com/ask-the-community-7/release-date-for-ai-tool-rollout-to-all-users-26131" target="_blank" rel="noreferrer">Release Date for AI Tool Rollout to All Users? | Figma Forum</a></p><p><strong>一句话摘要</strong>: Figma AI工具仍在有限测试阶段，逐步向用户推出。</p><p><strong>能解决什么问题</strong>: 解决设计师在UI/UX设计中自动化和效率问题。</p><p><strong>产品应用</strong>: 可以应用于产品设计，提高设计效率和质量。</p><p><strong>示例场景</strong>: 设计师使用Figma AI自动生成布局和元素。</p><hr><h3 id="_7-近期ai产品发布概览-linkedin" tabindex="-1">7. 近期AI产品发布概览 - LinkedIn <a class="header-anchor" href="#_7-近期ai产品发布概览-linkedin" aria-label="Permalink to &quot;7. 近期AI产品发布概览 - LinkedIn&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.linkedin.com/top-content/innovation/ai-trends-and-innovations/recent-ai-product-launches" target="_blank" rel="noreferrer">Recent AI Product Launches - LinkedIn</a></p><p><strong>一句话摘要</strong>: OpenAI等公司推出了多项AI新功能，推动智能对话和商业应用发展。</p><p><strong>能解决什么问题</strong>: 提高AI的主动性，简化用户交互，降低开发成本，提升效率。</p><p><strong>产品应用</strong>: 可以应用于智能助手、电子商务、企业调研和代码开发等领域。</p><p><strong>示例场景</strong>: 通过ChatGPT Pulse获取基于聊天的每日研究卡片。</p><hr><h3 id="_8-notion-ai更新令人惊叹" tabindex="-1">8. Notion AI更新令人惊叹 <a class="header-anchor" href="#_8-notion-ai更新令人惊叹" aria-label="Permalink to &quot;8. Notion AI更新令人惊叹&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.reddit.com/r/Notion/comments/1n3av27/the_new_notion_ai_updates_are_incredible" target="_blank" rel="noreferrer">The new Notion AI updates are incredible : r/Notion</a></p><p><strong>一句话摘要</strong>: Notion AI的新功能允许用户直接从互联网抓取信息填充数据库。</p><p><strong>能解决什么问题</strong>: 解决手动数据录入效率低下和信息更新不及时的问题。</p><p><strong>产品应用</strong>: 适用于需要快速整合网络信息到数据库的产品，如项目管理和个人目标规划。</p><p><strong>示例场景</strong>: 项目管理者可以利用Notion AI自动填充项目进度和资源信息。</p><hr><h3 id="_9-在figma设计中使用ai工具" tabindex="-1">9. 在Figma设计中使用AI工具 <a class="header-anchor" href="#_9-在figma设计中使用ai工具" aria-label="Permalink to &quot;9. 在Figma设计中使用AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://help.figma.com/hc/en-us/articles/23870272542231-Use-AI-tools-in-Figma-Design" target="_blank" rel="noreferrer">Use AI tools in Figma Design</a></p><p><strong>一句话摘要</strong>: Figma设计中的AI工具可帮助用户快速找到设计资源并创建初稿。</p><p><strong>能解决什么问题</strong>: 解决设计资源查找困难和手动创建设计初稿耗时的问题。</p><p><strong>产品应用</strong>: 适用于付费计划用户，通过AI工具快速探索设计可能性。</p><p><strong>示例场景</strong>: 设计师使用Figma AI将截图转换为可编辑的矢量图形。</p><hr><h3 id="_10-chatgpt制造商openai发布浏览器挑战谷歌" tabindex="-1">10. ChatGPT制造商OpenAI发布浏览器挑战谷歌 <a class="header-anchor" href="#_10-chatgpt制造商openai发布浏览器挑战谷歌" aria-label="Permalink to &quot;10. ChatGPT制造商OpenAI发布浏览器挑战谷歌&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.bbc.com/news/articles/c07mz10m1k9o" target="_blank" rel="noreferrer">ChatGPT-maker OpenAI releases web browser to rival Google</a></p><p><strong>一句话摘要</strong>: OpenAI推出AI浏览器Atlas，旨在挑战谷歌Chrome浏览器。</p><p><strong>能解决什么问题</strong>: 解决传统浏览器搜索效率低和用户体验差的问题。</p><p><strong>产品应用</strong>: 可以应用于个人电脑，通过AI技术提升搜索效率和个性化体验。</p><p><strong>示例场景</strong>: 用户在Atlas浏览器中直接用自然语言搜索信息。</p><hr>',75)])])}const _=t(e,[["render",i]]);export{d as __pageData,_ as default};
